<div class="page-title"><div><em>CUSTOMER PROFILE</em><h1><?=html_escape($customer['first_name'].' '.$customer['last_name'])?></h1><p><?=html_escape($customer['email'])?> · <?=html_escape($customer['phone']??'')?></p></div><div class="page-title-actions"><span class="<?=status_class($customer['status'])?>"><?=ucfirst($customer['status'])?></span><a class="outline" href="<?=site_url('admin/customers/'.$customer['id'].'/edit')?>">✎ Edit account</a><?php if($customer['status']==='active'):?><?=form_open('admin/customers/'.$customer['id'].'/login-as',array('class'=>'inline-form'))?><button class="btn" type="submit">↗ Login as customer</button></form><?php endif?></div></div><section class="panel admin-actions"><div><h3>Account access</h3><?=form_open('admin/customers/'.$customer['id'].'/status',array('class'=>'inline-controls'))?><select name="status"><option value="active" <?=$customer['status']==='active'?'selected':''?>>Active</option><option value="pending" <?=$customer['status']==='pending'?'selected':''?>>Pending</option><option value="suspended" <?=$customer['status']==='suspended'?'selected':''?>>Suspended</option><option value="closed" <?=$customer['status']==='closed'?'selected':''?>>Closed</option></select><button class="outline">Update status</button></form></div><div><h3>Balance adjustment</h3><?=form_open('admin/customers/'.$customer['id'].'/adjust',array('class'=>'inline-controls'))?><select name="account_id"><?php foreach($customer['accounts'] as $a):?><option value="<?=$a['id']?>"><?=html_escape($a['name'])?> •<?=substr($a['account_number'],-4)?></option><?php endforeach?></select><select name="direction"><option value="credit">Credit</option><option value="debit">Debit</option></select><input type="number" name="amount" step="0.01" min="0.01" placeholder="Amount" required><input name="note" placeholder="Adjustment note"><button class="btn">Apply</button></form></div><div><h3>KYC verification</h3><?=form_open('admin/customers/'.$customer['id'].'/kyc',array('class'=>'inline-controls'))?><select name="kyc_status"><option value="pending" <?=$customer['kyc_status']==='pending'?'selected':''?>>Pending</option><option value="verified" <?=$customer['kyc_status']==='verified'?'selected':''?>>Verified</option><option value="rejected" <?=$customer['kyc_status']==='rejected'?'selected':''?>>Rejected</option></select><span class="kyc-badge kyc-<?=html_escape($customer['kyc_status'])?>"><?=ucfirst($customer['kyc_status'])?></span><button class="outline">Update KYC</button></form></div></section><div class="stats"><?php foreach($customer['accounts'] as $a):?><div><i>▣</i><span><?=html_escape($a['name'])?><b><?=money($a['available_balance'])?></b><small><?=$a['account_number']?> · <?=ucfirst($a['status'])?></small></span><?php if($a['status']==='frozen'||$a['status']==='closed'):?><span class="status status-<?=$a['status']?>"><?=ucfirst($a['status'])?></span><?php endif?><form method="post" action="<?=site_url('admin/accounts/'.$a['id'].'/status')?>" class="inline-controls acc-admin-status"><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><select name="status"><option value="active" <?=$a['status']==='active'?'selected':''?>>Active</option><option value="frozen" <?=$a['status']==='frozen'?'selected':''?>>Frozen</option><option value="closed" <?=$a['status']==='closed'?'selected':''?>>Closed</option></select><button class="outline">Set</button></form></div><?php endforeach?></div><div class="grid two admin-grid" style="margin-bottom:17px"><section class="panel"><div class="panel-head"><div><h2>Cards</h2><p><?=count($customer['cards'])?> on file</p></div></div><div class="data-table"><div class="tr th"><span>Card</span><span>Status</span><span>Frozen</span></div><?php foreach($customer['cards'] as $c):?><div class="tr"><span>•<?=$c['last_four']?> <?=html_escape($c['network'])?></span><span class="<?=status_class($c['status'])?>"><?=ucfirst($c['status'])?></span><span><?=$c['is_frozen']?'Yes':'No'?></span></div><?php endforeach?><?php if(!$customer['cards']):?><div class="bell-empty">No cards.</div><?php endif?></div></section><section class="panel"><div class="panel-head"><div><h2>Loans</h2><p><?=count($customer['loans'])?> records</p></div></div><div class="data-table"><div class="tr th"><span>Type</span><span>Outstanding</span><span>Status</span></div><?php foreach($customer['loans'] as $l):?><div class="tr"><span><?=html_escape($l['type'])?></span><strong><?=money($l['outstanding_balance'])?></strong><span class="<?=status_class($l['status'])?>"><?=ucfirst($l['status'])?></span></div><?php endforeach?><?php if(!$customer['loans']):?><div class="bell-empty">No loans.</div><?php endif?></div></section></div><section class="panel"><div class="panel-head"><div><h2>Support tickets</h2><p><?=count($customer['tickets'])?> requests</p></div></div><div class="data-table"><div class="tr th"><span>Subject</span><span>Status</span></div><?php foreach($customer['tickets'] as $tk):?><div class="tr"><span><a style="color:#1468e5;font-weight:700" href="<?=site_url('admin/tickets/'.$tk['id'])?>"><?=html_escape($tk['subject'])?></a></span><span class="<?=status_class($tk['status'])?>"><?=ucwords(str_replace('_',' ',$tk['status']))?></span></div><?php endforeach?><?php if(!$customer['tickets']):?><div class="bell-empty">No tickets.</div><?php endif?></div></section><section class="panel"><div class="panel-head"><div><h2>Recent transactions</h2><p>Customer account activity</p></div></div><div class="data-table transaction-table"><div class="tr th"><span>Transaction</span><span>Date</span><span>Account</span><span>Amount</span><span>Status</span></div><?php foreach($customer['transactions'] as $t):?><div class="tr"><span class="name"><i><?=transaction_icon($t['type'])?></i><b><?=html_escape($t['description'])?><small><?=$t['reference']?></small></b></span><span><?=date('M j, Y',strtotime($t['transaction_date']))?></span><span>•••• <?=substr($t['account_number'],-4)?></span><strong class="<?=$t['type']?>"><?=money($t['amount'])?></strong><span class="<?=status_class($t['status'])?>"><?=ucfirst($t['status'])?></span></div><?php endforeach?></div></section>
